7	#include "mimalloc.h"
8	#include "mimalloc-stats.h"
9	#include "mimalloc/internal.h"
10	#include "mimalloc/atomic.h"
11	#include "mimalloc/prim.h"       // _mi_prim_clock_now, mi_process_info_t
12	#include "mimalloc/prim-tls.h"
13	
14	#include <string.h> // memset
15	
16	#if defined(_MSC_VER) && (_MSC_VER < 1920)
17	#pragma warning(disable:4204)  // non-constant aggregate initializer
18	#endif
19	
20	/* -----------------------------------------------------------
21	  Statistics operations
22	----------------------------------------------------------- */
23	
24	static void mi_stat_update_mt(mi_stat_count_t* stat, int64_t amount) {
25	  if (amount == 0) return;
26	  // add atomically
27	  int64_t current = mi_atomic_addi64_relaxed(&stat->current, amount);
28	  mi_atomic_maxi64_relaxed(&stat->peak, current + amount);
29	  if (amount > 0) {
30	    mi_atomic_addi64_relaxed(&stat->total, amount);
31	  }
32	}
33	
34	static void mi_stat_update(mi_stat_count_t* stat, int64_t amount) {
35	  if (amount == 0) return;
36	  // add thread local
37	  stat->current += amount;
38	  if (stat->current > stat->peak) { stat->peak = stat->current; }
39	  if (amount > 0) { stat->total += amount; }
40	}
41	
42	
43	void __mi_stat_counter_increase_mt(mi_stat_counter_t* stat, size_t amount) {
44	  mi_atomic_addi64_relaxed(&stat->total, (int64_t)amount);
45	}
46	
47	void __mi_stat_counter_increase(mi_stat_counter_t* stat, size_t amount) {
48	  stat->total += amount;
49	}
50	
51	void __mi_stat_increase_mt(mi_stat_count_t* stat, size_t amount) {
52	  mi_stat_update_mt(stat, (int64_t)amount);
53	}
54	void __mi_stat_increase(mi_stat_count_t* stat, size_t amount) {
55	  mi_stat_update(stat, (int64_t)amount);
56	}
57	
58	void __mi_stat_decrease_mt(mi_stat_count_t* stat, size_t amount) {
59	  mi_stat_update_mt(stat, -((int64_t)amount));
60	}
61	void __mi_stat_decrease(mi_stat_count_t* stat, size_t amount) {
62	  mi_stat_update(stat, -((int64_t)amount));
63	}
64	
65	
66	// Adjust stats to compensate; for example before committing a range,
67	// first adjust downwards with parts that were already committed so
68	// we avoid double counting.
69	static void mi_stat_adjust_mt(mi_stat_count_t* stat, int64_t amount) {
70	  if (amount == 0) return;
71	  // adjust atomically
72	  const size_t peak = mi_atomic_loadi64_relaxed((_Atomic(int64_t)*)&stat->peak);
73	  mi_atomic_addi64_relaxed(&stat->current, amount);
74	  const size_t prev_total = mi_atomic_addi64_relaxed(&stat->total, amount);
75	  if (prev_total == peak) { mi_atomic_addi64_relaxed(&stat->peak, amount); }
76	}
77	
78	static void mi_stat_adjust(mi_stat_count_t* stat, int64_t amount) {
79	  if (amount == 0) return;
80	  stat->current += amount;
81	  if (stat->total==stat->peak) { stat->peak += amount; }
82	  stat->total += amount;  
83	}
84	
85	void __mi_stat_adjust_increase_mt(mi_stat_count_t* stat, size_t amount) {
86	  mi_stat_adjust_mt(stat, (int64_t)amount);
87	}
88	void __mi_stat_adjust_increase(mi_stat_count_t* stat, size_t amount) {
89	  mi_stat_adjust(stat, (int64_t)amount);
90	}
91	void __mi_stat_adjust_decrease_mt(mi_stat_count_t* stat, size_t amount) {
92	  mi_stat_adjust_mt(stat, -((int64_t)amount));
93	}
94	void __mi_stat_adjust_decrease(mi_stat_count_t* stat, size_t amount) {
95	  mi_stat_adjust(stat, -((int64_t)amount));
96	}
97	
98	
99	// must be thread safe as it is called from stats_merge
100	static void mi_stat_count_add_mt(mi_stat_count_t* stat, const mi_stat_count_t* src) {
101	  if (stat==src) return;
102	  mi_atomic_void_addi64_relaxed(&stat->total, &src->total);
103	  const int64_t src_peak = mi_atomic_loadi64_relaxed((_Atomic(int64_t)*)&src->peak);
104	  const int64_t src_current = mi_atomic_loadi64_relaxed((_Atomic(int64_t)*)&src->current);
105	  const int64_t prev_current = mi_atomic_addi64_relaxed(&stat->current, src_current);
106	
107	  // Global current plus thread peak approximates new global peak
108	  // note: peak scores do not really work across threads.
109	  // we used to just add them together but that often overestimates in practice.
110	  // similarly, max does not seem to work well. The current approach
111	  // by Artem Kharytoniuk (@artem-lunarg) seems to work better, see PR#1112
112	  // for a longer description.  
113	  mi_atomic_maxi64_relaxed(&stat->peak, prev_current + src_peak);
114	}
115	
116	static void mi_stat_counter_add_mt(mi_stat_counter_t* stat, const mi_stat_counter_t* src) {
117	  if (stat==src) return;
118	  mi_atomic_void_addi64_relaxed(&stat->total, &src->total);
119	}
120	
121	#define MI_STAT_COUNT(stat)    mi_stat_count_add_mt(&stats->stat, &src->stat);
122	#define MI_STAT_COUNTER(stat)  mi_stat_counter_add_mt(&stats->stat, &src->stat);
123	
124	// must be thread safe as it is called from stats_merge
125	static void mi_stats_add(mi_stats_t* stats, const mi_stats_t* src) {
126	  if (stats==NULL || src==NULL || stats==src) return;
127	
128	  // copy all fields
129	  MI_STAT_FIELDS()
130	
131	  #if MI_STAT>1
132	  for (size_t i = 0; i <= MI_BIN_HUGE; i++) {
133	    mi_stat_count_add_mt(&stats->malloc_bins[i], &src->malloc_bins[i]);
134	  }
135	  #endif
136	  for (size_t i = 0; i <= MI_BIN_HUGE; i++) {
137	    mi_stat_count_add_mt(&stats->page_bins[i], &src->page_bins[i]);
138	  }
139	  for (size_t i = 0; i < MI_CBIN_COUNT; i++) {
140	    mi_stat_count_add_mt(&stats->chunk_bins[i], &src->chunk_bins[i]);
141	  }
142	}
143	
144	#undef MI_STAT_COUNT
145	#undef MI_STAT_COUNTER
146	
147	/* -----------------------------------------------------------
148	  Display statistics
149	----------------------------------------------------------- */
150	
151	// unit > 0 : size in binary bytes
152	// unit == 0: count as decimal
153	// unit < 0 : count in binary
154	static void mi_printf_amount(int64_t n, int64_t unit, mi_output_fun* out, void* arg, bool limitwidth) {
155	  char buf[32]; _mi_memzero_var(buf);
156	  int  len = 32;
157	  const char* suffix = (unit <= 0 ? " " : "B");
158	  const int64_t base = (unit == 0 ? 1000 : 1024);
159	  if (unit>0) n *= unit;
160	
161	  const int64_t pos = (n < 0 ? -n : n);
162	  if (pos < base) {
163	    if (n!=1 || suffix[0] != 'B') {  // skip printing 1 B for the unit column
164	      _mi_snprintf(buf, len, "%lld   %-3s", (long long)n, (n==0 ? "" : suffix));
165	    }
166	  }
167	  else {
168	    int64_t divider = base;
169	    const char* magnitude = "K";
170	    if (pos >= divider*base) { divider *= base; magnitude = "M"; }
171	    if (pos >= divider*base) { divider *= base; magnitude = "G"; }
172	    const int64_t tens = (n / (divider/10));
173	    const long whole = (long)(tens/10);
174	    const long frac1 = (long)(tens%10);
175	    char unitdesc[8];
176	    _mi_snprintf(unitdesc, 8, "%s%s%s", magnitude, (base==1024 ? "i" : ""), suffix);
177	    _mi_snprintf(buf, len, "%ld.%ld %-3s", whole, (frac1 < 0 ? -frac1 : frac1), unitdesc);
178	  }
179	  if (limitwidth) {
180	    _mi_fprintf(out, arg, "%12s", buf);
181	  }
182	  else {
183	    _mi_fprintf(out, arg, "%s", buf);
184	  }
185	}
186	
187	
188	static void mi_print_amount(int64_t n, int64_t unit, mi_output_fun* out, void* arg) {
189	  mi_printf_amount(n,unit,out,arg,true);
190	}
191	
192	static void mi_print_count(int64_t n, int64_t unit, mi_output_fun* out, void* arg) {
193	  if (unit==1) _mi_fprintf(out, arg, "%12s"," ");
194	          else mi_print_amount(n,0,out,arg);
195	}
196	
197	static void mi_stat_print_ex(const mi_stat_count_t* stat, const char* msg, int64_t unit, mi_output_fun* out, void* arg, const char* notok ) {
198	  _mi_fprintf(out, arg,"  %-10s:", msg);
199	  if (unit != 0) {
200	    if (unit > 0) {
201	      mi_print_amount(stat->peak, unit, out, arg);
202	      mi_print_amount(stat->total, unit, out, arg);
203	      // mi_print_amount(stat->freed, unit, out, arg);
204	      mi_print_amount(stat->current, unit, out, arg);
205	      mi_print_amount(unit, 1, out, arg);
206	      mi_print_count(stat->total, unit, out, arg);
207	    }
208	    else {
209	      mi_print_amount(stat->peak, -1, out, arg);
210	      mi_print_amount(stat->total, -1, out, arg);
211	      // mi_print_amount(stat->freed, -1, out, arg);
212	      mi_print_amount(stat->current, -1, out, arg);
213	      if (unit == -1) {
214	        _mi_fprintf(out, arg, "%24s", "");
215	      }
216	      else {
217	        mi_print_amount(-unit, 1, out, arg);
218	        mi_print_count((stat->total / -unit), 0, out, arg);
219	      }
220	    }
221	    if (stat->current != 0) {
222	      _mi_fprintf(out, arg, "  ");
223	      _mi_fprintf(out, arg, "%s", (notok == NULL ? "not all freed" : notok));
224	      _mi_fprintf(out, arg, "\n");
225	    }
226	    else {
227	      _mi_fprintf(out, arg, "  ok\n");
228	    }
229	  }
230	  else {
231	    mi_print_amount(stat->peak, 0, out, arg);
232	    mi_print_amount(stat->total, 0, out, arg);
233	    mi_print_amount(stat->current, 0, out, arg);
234	    _mi_fprintf(out, arg, "\n");
235	  }
236	}
237	
238	static void mi_stat_print(const mi_stat_count_t* stat, const char* msg, int64_t unit, mi_output_fun* out, void* arg) {
239	  mi_stat_print_ex(stat, msg, unit, out, arg, NULL);
240	}
241	
242	#if MI_STAT>1
243	static void mi_stat_total_print(const mi_stat_count_t* stat, const char* msg, int64_t unit, mi_output_fun* out, void* arg) {
244	  _mi_fprintf(out, arg, "  %-10s:", msg);
245	  _mi_fprintf(out, arg, "%12s", " ");  // no peak
246	  mi_print_amount(stat->total, unit, out, arg);
247	  _mi_fprintf(out, arg, "\n");
248	}
249	#endif
250	
251	static void mi_stat_counter_print(const mi_stat_counter_t* stat, const char* msg, mi_output_fun* out, void* arg ) {
252	  _mi_fprintf(out, arg, "  %-10s:", msg);
253	  mi_print_amount(stat->total, 0, out, arg);
254	  _mi_fprintf(out, arg, "\n");
255	}
256	
257	static void mi_stat_counter_print_size(const mi_stat_counter_t* stat, const char* msg, mi_output_fun* out, void* arg ) {
258	  _mi_fprintf(out, arg, "  %-10s:", msg);
259	  mi_print_amount(stat->total, 1, out, arg);
260	  _mi_fprintf(out, arg, "\n");
261	}
262	
263	static void mi_stat_average_print(int64_t count, int64_t total, const char* msg, mi_output_fun* out, void* arg) {
264	  const int64_t avg_tens = (count == 0 ? 0 : (total*10 / count));
265	  const int64_t avg_whole = avg_tens/10;
266	  const int64_t avg_frac1 = avg_tens%10;
267	  _mi_fprintf(out, arg, "  %-10s: %5lld.%lld avg\n", msg, avg_whole, avg_frac1);
268	}
269	
270	
271	static void mi_print_header(const char* name,mi_output_fun* out, void* arg ) {
272	  _mi_fprintf(out, arg, " %-11s %11s %11s %11s %11s %11s\n",
273	                        name, "peak   ", "total   ", "current   ", "block   ", "total#   ");
274	}
275	
276	#if MI_STAT>1
277	static bool mi_stats_print_bins(const mi_stat_count_t* bins, size_t max, mi_output_fun* out, void* arg) {
278	  bool found = false;
279	  char buf[64];
280	  for (size_t i = 0; i <= max; i++) {
281	    if (bins[i].total > 0) {
282	      found = true;
283	      const size_t unit = _mi_bin_size((uint8_t)i);
284	      const char* pagekind = (unit <= MI_SMALL_MAX_OBJ_SIZE ? "S" :
285	                               (unit <= MI_MEDIUM_MAX_OBJ_SIZE ? "M" :
286	                                 (unit <= MI_LARGE_MAX_OBJ_SIZE ? "L" : "H")));
287	      _mi_snprintf(buf, 64, "bin%2s  %3lu", pagekind, (long)i);
288	      mi_stat_print(&bins[i], buf, (int64_t)unit, out, arg);
289	    }
290	  }
291	  if (found) {
292	    _mi_fprintf(out, arg, "\n");
293	  }
294	  return found;
295	}
296	#endif
297	
298	
299	
300	//------------------------------------------------------------
301	// Use an output wrapper for line-buffered output
302	// (which is nice when using loggers etc.)
303	//------------------------------------------------------------
304	typedef struct buffered_s {
305	  mi_output_fun* out;   // original output function
306	  void*          arg;   // and state
307	  char*          buf;   // local buffer of at least size `count+1`
308	  size_t         used;  // currently used chars `used <= count`
309	  size_t         count; // total chars available for output
310	} buffered_t;
311	
312	static void mi_buffered_flush(buffered_t* buf) {
313	  buf->buf[buf->used] = 0;
314	  _mi_fputs(buf->out, buf->arg, NULL, buf->buf);
315	  buf->used = 0;
316	}
317	
318	static void mi_cdecl mi_buffered_out(const char* msg, void* arg) {
319	  buffered_t* buf = (buffered_t*)arg;
320	  if (msg==NULL || buf==NULL) return;
321	  for (const char* src = msg; *src != 0; src++) {
322	    char c = *src;
323	    if (buf->used >= buf->count) mi_buffered_flush(buf);
324	    mi_assert_internal(buf->used < buf->count);
325	    buf->buf[buf->used++] = c;
326	    if (c == '\n') mi_buffered_flush(buf);
327	  }
328	}
329	
330	//------------------------------------------------------------
331	// Print statistics
332	//------------------------------------------------------------
333	
334	mi_decl_export void mi_process_info_print_out(mi_output_fun* out, void* arg) mi_attr_noexcept
335	{
336	  size_t elapsed;
337	  size_t user_time;
338	  size_t sys_time;
339	  size_t current_rss;
340	  size_t peak_rss;
341	  size_t current_commit;
342	  size_t peak_commit;
343	  size_t page_faults;
344	  mi_process_info(&elapsed, &user_time, &sys_time, &current_rss, &peak_rss, &current_commit, &peak_commit, &page_faults);
345	  _mi_fprintf(out, arg, "  %-10s: %5zu.%03zu s\n", "elapsed", elapsed/1000, elapsed%1000);
346	  _mi_fprintf(out, arg, "  %-10s: user: %zu.%03zu s, system: %zu.%03zu s, faults: %zu, peak rss: ", "process",
347	    user_time/1000, user_time%1000, sys_time/1000, sys_time%1000, page_faults);
348	  mi_printf_amount((int64_t)peak_rss, 1, out, arg, false);
349	  if (peak_commit > 0) {
350	    _mi_fprintf(out, arg, ", peak commit: ");
351	    mi_printf_amount((int64_t)peak_commit, 1, out, arg, false);
352	  }
353	  _mi_fprintf(out, arg, "\n");
354	}
