550	mi_msecs_t _mi_clock_start(void) {
551	  if (mi_clock_diff == 0.0) {
552	    mi_msecs_t t0 = _mi_clock_now();
553	    mi_clock_diff = _mi_clock_now() - t0;
554	  }
555	  return _mi_clock_now();
556	}
