567	
568	mi_decl_export void mi_process_info(size_t* elapsed_msecs, size_t* user_msecs, size_t* system_msecs, size_t* current_rss, size_t* peak_rss, size_t* current_commit, size_t* peak_commit, size_t* page_faults) mi_attr_noexcept
569	{
570	  mi_process_info_t pinfo;
571	  _mi_memzero_var(pinfo);
572	  pinfo.elapsed        = _mi_clock_end(mi_process_start);
573	  { const mi_subproc_t* subproc = _mi_subproc_main();
574	    if (subproc!=NULL) {
575	      const int64_t current = mi_atomic_loadi64_relaxed((_Atomic(int64_t)*)(&subproc->stats.committed.current));
576	      const int64_t peak    = mi_atomic_loadi64_relaxed((_Atomic(int64_t)*)(&subproc->stats.committed.peak));
577	      pinfo.current_commit  = (current < 0 ? 0 : (current < PTRDIFF_MAX ? (size_t)current : PTRDIFF_MAX));
578	      pinfo.peak_commit     = (peak < 0 ? 0 : (peak < PTRDIFF_MAX ? (size_t)peak : PTRDIFF_MAX));
579	    }  
580	  }
581	  pinfo.current_rss    = pinfo.current_commit;
582	  pinfo.peak_rss       = pinfo.peak_commit;
583	  pinfo.utime          = 0;
584	  pinfo.stime          = 0;
585	  pinfo.page_faults    = 0;
586	
587	  _mi_prim_process_info(&pinfo);
588	
589	  if (elapsed_msecs!=NULL)  *elapsed_msecs  = (pinfo.elapsed < 0 ? 0 : (pinfo.elapsed < (mi_msecs_t)PTRDIFF_MAX ? (size_t)pinfo.elapsed : PTRDIFF_MAX));
590	  if (user_msecs!=NULL)     *user_msecs     = (pinfo.utime < 0 ? 0 : (pinfo.utime < (mi_msecs_t)PTRDIFF_MAX ? (size_t)pinfo.utime : PTRDIFF_MAX));
591	  if (system_msecs!=NULL)   *system_msecs   = (pinfo.stime < 0 ? 0 : (pinfo.stime < (mi_msecs_t)PTRDIFF_MAX ? (size_t)pinfo.stime : PTRDIFF_MAX));
592	  if (current_rss!=NULL)    *current_rss    = pinfo.current_rss;
593	  if (peak_rss!=NULL)       *peak_rss       = pinfo.peak_rss;
594	  if (current_commit!=NULL) *current_commit = pinfo.current_commit;
595	  if (peak_commit!=NULL)    *peak_commit    = pinfo.peak_commit;
596	  if (page_faults!=NULL)    *page_faults    = pinfo.page_faults;
597	}
