659	
660	typedef struct mi_json_buf_s {
661	  char*   buf;
662	  size_t  size;
663	  size_t  used;
664	  bool    can_realloc;
665	} mi_json_buf_t;
666	
667	static bool mi_json_buf_expand(mi_json_buf_t* hbuf) {
668	  if (hbuf==NULL) return false;
669	  if (hbuf->buf != NULL && hbuf->size>0) {
670	    hbuf->buf[hbuf->size-1] = 0;
671	  }
672	  if (hbuf->size > SIZE_MAX/2 || !hbuf->can_realloc) return false;
673	  const size_t newsize = (hbuf->size == 0 ? mi_good_size(12*MI_KiB) : 2*hbuf->size);
674	  char* const  newbuf  = (char*)mi_rezalloc(hbuf->buf, newsize);
675	  if (newbuf == NULL) return false;
676	  hbuf->buf = newbuf;
677	  hbuf->size = newsize;
678	  return true;
679	}
680	
681	static void mi_json_buf_print(mi_json_buf_t* hbuf, const char* msg) {
682	  if (msg==NULL || hbuf==NULL) return;
683	  if (hbuf->used + 1 >= hbuf->size && !hbuf->can_realloc) return;
684	  for (const char* src = msg; *src != 0; src++) {
685	    char c = *src;
686	    if (hbuf->used + 1 >= hbuf->size) {
687	      if (!mi_json_buf_expand(hbuf)) return;
688	    }
689	    mi_assert_internal(hbuf->used < hbuf->size);
690	    hbuf->buf[hbuf->used++] = c;
691	  }
692	  mi_assert_internal(hbuf->used < hbuf->size);
693	  hbuf->buf[hbuf->used] = 0;
694	}
