756	static char* mi_stats_get_json_from(const mi_stats_t* stats, size_t output_size, char* output_buf) mi_attr_noexcept {
757	  if (stats==NULL || stats->size!=sizeof(mi_stats_t) || stats->version!=MI_STAT_VERSION) return NULL;
758	  mi_json_buf_t hbuf = { NULL, 0, 0, true };
759	  if (output_size > 0 && output_buf != NULL) {
760	    _mi_memzero(output_buf, output_size);
761	    hbuf.buf = output_buf;
762	    hbuf.size = output_size;
763	    hbuf.can_realloc = false;
764	  }
765	  else {
